/**
 * Workspace deletion as a grace period: a deleted workspace is kept, inert, for
 * `DELETED_WORKSPACE_RETENTION_DAYS`; its owner may restore it inside that
 * window, and the retention sweep purges it once the window has closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runCleanupArchivedJob } from "@/server/jobs";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as invitationService from "@/server/services/invitation-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

const DAY_MS = 24 * 60 * 60 * 1000;
const T0 = new Date("2026-06-01T12:00:00.000Z");

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** Creates a tenant with its clock pinned to `T0`, so windows are predictable. */
async function freshTenant(slug: string): Promise<Tenant> {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(T0);
  return createTenant(slug);
}

function at(offsetMs: number): void {
  vi.setSystemTime(new Date(T0.getTime() + offsetMs));
}

function capture<K extends "organization.deleted" | "organization.restored">(
  type: K,
): Array<{ actorId: UserId | null; slug: string }> {
  const seen: Array<{ actorId: UserId | null; slug: string }> = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push({ actorId: payload.actorId, slug: payload.slug });
    }),
  );
  return seen;
}

async function deleteTenant(tenant: Tenant): Promise<void> {
  await organizationService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

describe("deleting a workspace", () => {
  it("keeps the rows, publishes organization.deleted and audits it", async () => {
    const tenant = await freshTenant("wsdel-audit");
    const seen = capture("organization.deleted");

    await deleteTenant(tenant);

    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.archivedAt).toBe(toIsoTimestamp(T0));
    expect(seen).toEqual([
      { actorId: tenant.userIds.owner, slug: "wsdel-audit" },
    ]);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action)).toContain("organization.deleted");
    expect(audit.find((row) => row.action === "organization.deleted")?.actorId).toBe(
      tenant.userIds.owner,
    );
  });

  it("refuses a second deletion with AlreadyArchivedError", async () => {
    const tenant = await freshTenant("wsdel-twice");
    await deleteTenant(tenant);

    await expect(deleteTenant(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("while a workspace is deleted", () => {
  it("is neither signed into by slug nor listed for its members", async () => {
    const tenant = await freshTenant("wsdel-hidden");
    await deleteTenant(tenant);

    await expect(orgRepo.findOrgBySlug("wsdel-hidden")).resolves.toBeNull();
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.member);
    expect(listed.map((org) => org.id)).not.toContain(tenant.org.id);
  });

  it("keeps its slug reserved", async () => {
    const tenant = await freshTenant("wsdel-reserved");
    await deleteTenant(tenant);

    const taken = await orgRepo.listTakenOrgSlugs("wsdel-reserved");
    expect(taken).toContain("wsdel-reserved");
  });

  it("refuses an invitation into it and leaves the invitation pending", async () => {
    const tenant = await freshTenant("wsdel-invite");
    const raw = randomToken(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "newcomer@wsdel-invite.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      hashToken(raw),
    );
    const newcomer = await userRepo.insertUser({
      email: "newcomer@wsdel-invite.test",
      name: "Newcomer",
      passwordHash: "seed",
    });
    await deleteTenant(tenant);

    await expect(
      invitationService.acceptInvitation(newcomer.id, { token: raw }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.email)).toContain("newcomer@wsdel-invite.test");
  });

  it("creates no notifications in it", async () => {
    const tenant = await freshTenant("wsdel-notify");
    await deleteTenant(tenant);

    const rows = await notificationService.notify(
      tenant.org.id,
      "member_joined",
      [tenant.userIds.member],
      {
        title: "A new member joined",
        body: "nobody should see this",
        href: "/settings/members",
        actorId: null,
      },
    );

    expect(rows).toEqual([]);
  });

  it("drops out of the rollup work list the jobs read", async () => {
    const tenant = await freshTenant("wsdel-rollup");
    await usageRepo.recomputeUsage(tenant.org.id);
    await deleteTenant(tenant);

    const ids: readonly OrgId[] = await usageRepo.listOrgIdsForRollup(100);
    expect(ids).not.toContain(tenant.org.id);
  });
});

describe("restoring a workspace", () => {
  it("lets the owner bring it back inside the window and publishes organization.restored", async () => {
    const tenant = await freshTenant("wsdel-restore");
    await deleteTenant(tenant);
    const seen = capture("organization.restored");

    at(DAY_MS);
    const restored = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(restored.archivedAt).toBeNull();
    await expect(orgRepo.findOrgBySlug("wsdel-restore")).resolves.toMatchObject({
      id: tenant.org.id,
    });
    expect(seen).toEqual([
      { actorId: tenant.userIds.owner, slug: "wsdel-restore" },
    ]);
  });

  it("refuses a member who is not an owner with PermissionDeniedError", async () => {
    const tenant = await freshTenant("wsdel-admin");
    await deleteTenant(tenant);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses a caller who is not a member with NotFoundError", async () => {
    const tenant = await freshTenant("wsdel-stranger");
    await deleteTenant(tenant);
    const stranger = await userRepo.insertUser({
      email: "stranger@wsdel-stranger.test",
      name: "Stranger",
      passwordHash: "seed",
    });

    await expect(
      organizationService.restoreOrganization(stranger.id, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("is gone once the window has closed, even before the sweep has run", async () => {
    const tenant = await freshTenant("wsdel-late");
    await deleteTenant(tenant);

    at(DELETED_WORKSPACE_RETENTION_DAYS * DAY_MS);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await freshTenant("wsdel-live");
    const seen = capture("organization.restored");

    const result = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(result).toEqual(tenant.org);
    expect(seen).toHaveLength(0);
  });
});

describe("the retention sweep", () => {
  it("leaves a deleted workspace alone while its window is open", async () => {
    const tenant = await freshTenant("wsdel-open");
    await deleteTenant(tenant);

    at((DELETED_WORKSPACE_RETENTION_DAYS - 1) * DAY_MS);
    await runCleanupArchivedJob(new Date(T0.getTime() + (DELETED_WORKSPACE_RETENTION_DAYS - 1) * DAY_MS));

    await expect(orgRepo.findOrgById(tenant.org.id)).resolves.not.toBeNull();
