    at(DELETED_WORKSPACE_RETENTION_DAYS * DAY_MS);
    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await orgRepo.insertOrg(
      { name: "Reborn", slug: "wsdel-purge", plan: "free" },
      tenant.userIds.owner,
    );
    expect(reborn.slug).toBe("wsdel-purge");
  });

  it("detaches a session that was pointed at the purged workspace", async () => {
    const tenant = await freshTenant("wsdel-session");
    await deleteTenant(tenant);

    const { getDb, sessions } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    getDb()
      .insert(sessions)
      .values({
        id: "01HZZZSESSION00000000000001",
        userId: tenant.userIds.owner,
        activeOrgId: tenant.org.id,
        tokenHash: hashToken("wsdel-session-token"),
        expiresAt: toIsoTimestamp(new Date(T0.getTime() + 365 * DAY_MS)),
        createdAt: toIsoTimestamp(T0),
        updatedAt: toIsoTimestamp(T0),
      })
      .run();

    await runCleanupArchivedJob(
      new Date(T0.getTime() + DELETED_WORKSPACE_RETENTION_DAYS * DAY_MS),
    );

    const row = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.id, "01HZZZSESSION00000000000001"))
      .get();
    expect(row?.activeOrgId).toBeNull();
  });
});

